int old_dir_fd; // File Descriptor for source directory
int new_dir_fd; // File Descriptor for destination directory
const char *old_rel_path = "source_file";
const char *new_rel_path = "new_link";
int flags = 0;

// Set up directory descriptors (e.g., via open() or AT_FDCWD)
old_dir_fd = open("dir_a", O_RDONLY | O_DIRECTORY);
new_dir_fd = AT_FDCWD; // Use current working directory

// Atomically create a hard link
int status = linkat(
    old_dir_fd,
    old_rel_path,
    new_dir_fd,
    new_rel_path,
    flags // Usually 0 for hard links
);

// Check status, then close FDs
if (status == 0) {
    close(old_dir_fd);
}
